var t=`0163-pasta-alla-gricia`;var i=`world-0163`;var n=`IT`;var s=`southern-europe`;var o=4;var r=24;var l={en:`Pasta alla Gricia`,ua:`Паста грича`};var u={en:`A classic dish from Italy, featuring guanciale, rigatoni, pecorino romano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: гуанчале, ригатоні, пекоріно романо. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`guanciale`,200,`g`]]},{en:`Cook the pasta in generously salted boiling water for about 10 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 10 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`rigatoni`,400,`g`],[`water`,1600,`ml`],[`table-salt`,10,`g`]]},{en:`Toss the cooked pasta with the sauce, adding a splash of reserved pasta water until everything is evenly coated.`,ua:`Змішайте готову пасту із соусом, додаючи потроху збережену воду з-під пасти, доки соус рівномірно вкриє її.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:4,i:[[`pecorino-romano`,125,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var c={slug:t,id:i,country:`IT`,region:s,servings:4,minutes:24,title:l,text:u,steps:g};export{n as country,c as default,i as id,r as minutes,s as region,o as servings,t as slug,g as steps,u as text,l as title};